SELECT dept_name, CASE WHEN budget >= 3151000 THEN 'high' WHEN budget >= 1602000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget, SUM(CASE WHEN dept_name = 'Finance' THEN budget ELSE 0 END) AS finance_budget FROM departments WHERE (location NOT IN ('New York', 'Tokyo', 'Chiang Mai') AND dept_name <> 'HR') OR location IN ('New York', 'Bangkok', 'Singapore') GROUP BY dept_name, CASE WHEN budget >= 3151000 THEN 'high' WHEN budget >= 1602000 THEN 'mid' ELSE 'low' END ORDER BY dept_name
